# Alpine mkimage profile for the PandaBoard (OMAP4430) audio appliance.
# Loaded by aports/scripts/mkimage.sh from ~/.mkimage (scripts/build-image.sh
# copies it there). The output tarball is unpacked onto the SD card's FAT
# partition; U-Boot itself is written raw by scripts/write-sdcard.sh.

pandaboard_extlinux_gen() {
	cat <<-EOF
	# Generated by mkimg.pandaboard.sh
	DEFAULT pandaboard
	TIMEOUT 10
	LABEL pandaboard
		MENU LABEL Alpine Linux (pandaboard)
		KERNEL /boot/vmlinuz-pandaboard
		INITRD /boot/initramfs-pandaboard
		FDT /boot/dtbs-pandaboard/omap4-panda.dtb
		APPEND $initfs_cmdline $kernel_cmdline
	EOF
}

build_pandaboard_extlinux() {
	mkdir -p "$DESTDIR"/extlinux
	pandaboard_extlinux_gen > "$DESTDIR"/extlinux/extlinux.conf
}

section_pandaboard_extlinux() {
	[ -n "$pandaboard_extlinux" ] || return 0
	build_section pandaboard_extlinux $(pandaboard_extlinux_gen | checksum)
}

profile_pandaboard() {
	profile_base
	title="PandaBoard"
	desc="Diskless Alpine for the PandaBoard (OMAP4430) audio appliance."
	image_ext="tar.gz"
	arch="armv7"
	kernel_flavors="pandaboard"
	kernel_addons=
	initfs_features="base mmc squashfs usb"
	# No "quiet": the boot log on serial is the main debugging tool.
	initfs_cmdline="modules=loop,squashfs,sd-mod,usb-storage"
	kernel_cmdline="console=ttyS2,115200n8"
	# hci_ll builds the firmware name at runtime, so modinfo doesn't list it.
	modloopfw="ti-connectivity/TIInit_7.2.31.bts.zst"
	pandaboard_extlinux=yes
	# U-Boot + extlinux boot; no GRUB/EFI (profile_base enables it for ARM).
	grub_mod=
	apks="alpine-base apk-cron avahi busybox chrony dbus doas openssh openssl tzdata wget
		e2fsprogs dosfstools alsa-utils bluez bluez-deprecated"
	apkovl="genapkovl-pandaboard.sh"
	hostname="panda"
}
